using System;
using System.Collections.Generic;
using System.Threading;

/// <summary>
/// Migrated from .NET Framework to .NET 8.
/// Replaced Thread.Interrupt + Thread.Abort with cooperative CancellationToken.
/// Replaced ManualResetEvent.WaitOne() with WaitHandle.WaitAny + token.WaitHandle.
/// </summary>
public class EventProcessor : IDisposable
{
    private readonly ManualResetEvent _newEvent = new ManualResetEvent(false);
    private readonly Queue<string> _queue = new Queue<string>();
    private Thread? _thread;
    private readonly object _lock = new object();
    private readonly CancellationTokenSource _cts = new CancellationTokenSource();

    public void Start()
    {
        _thread = new Thread(RunLoop);
        _thread.Start();
    }

    private void RunLoop()
    {
        var token = _cts.Token;
        var waitHandles = new WaitHandle[] { _newEvent, token.WaitHandle };

        while (!token.IsCancellationRequested)
        {
            // WaitAny returns the index of the handle that was signaled.
            // Index 0 = _newEvent (new item), Index 1 = cancellation requested.
            int signaled = WaitHandle.WaitAny(waitHandles);

            if (signaled == 1 || token.IsCancellationRequested)
                break;

            _newEvent.Reset();

            string? item = null;
            lock (_lock)
            {
                if (_queue.Count > 0)
                    item = _queue.Dequeue();
            }

            if (item != null)
                Handle(item);
        }
    }

    public void Enqueue(string item)
    {
        lock (_lock) { _queue.Enqueue(item); }
        _newEvent.Set();
    }

    public void Stop()
    {
        _cts.Cancel();          // signals token.WaitHandle, waking WaitAny
        _thread?.Join(5000);    // wait up to 5s for clean exit
    }

    public void Dispose()
    {
        Stop();
        _cts.Dispose();
        _newEvent.Dispose();
    }

    private void Handle(string item)
    {
        // your processing logic here
    }
}

